// build.gradle.kts
implementation(
  "com.revenuecat.purchases:" +
    "purchases:10.8.0"
)

// Includes Paywalls for Compose
implementation(
  "com.revenuecat.purchases:" +
    "purchases-ui:10.8.0"
)

class MainApplication : Application() {
  override fun onCreate() {
    super.onCreate()
    Purchases.logLevel = LogLevel.DEBUG
    Purchases.configure(
      PurchasesConfiguration.Builder(
        this, "goog_public_sdk_key"
      ).build()
    )
  }
}

// Start anonymous
Purchases.configure(config)

// Identify after sign-in
Purchases.sharedInstance.logIn(appUserId) {
  customerInfo, created, error ->
  // refresh access
}

val offering = try {
  Purchases.sharedInstance
    .awaitOfferings()
    .current
} catch (e: PurchasesException) {
  logger.warn(e) { "Offerings unavailable" }
  null
}

val annual = offering?.annual?.storeProduct

Purchases.sharedInstance.getCustomerInfoWith(
  onError = { error ->
    // keep the last known access state
  },
  onSuccess = { customerInfo ->
    val hasPro = customerInfo
      .entitlements["pro"]
      ?.isActive == true
  }
)

when (checkoutConfig.route) {
  PLAY_BILLING -> showPlayPaywall()
  USER_CHOICE  -> showBillingChoice()
  EXTERNAL_WEB -> openApprovedLink()
  else         -> showPlayPaywall()
}

